const body = $json.body ?? $json;
const supportedLanguages = ['typescript', 'javascript', 'python', 'php'];
const supportedDocTypes = ['technical', 'operational'];
const code = String(body.code ?? '').trim();
const language = String(body.language ?? '').trim().toLowerCase();
const docType = String(body.doc_type ?? '').trim().toLowerCase();
const model = typeof body.model === 'string' && body.model.trim() ? body.model.trim() : 'openai/gpt-4o-mini';
const promptVersion = Number.isInteger(body.prompt_version) && body.prompt_version > 0 ? body.prompt_version : undefined;
if (!code) throw new Error('O campo code e obrigatorio.');
if (!supportedLanguages.includes(language)) throw new Error(`Linguagem nao suportada para documentacao: ${language || '(vazia)'}.`);
if (!supportedDocTypes.includes(docType)) throw new Error(`Tipo de documentacao nao suportado: ${docType || '(vazio)'}.`);
const inputPayload = { code, language, doc_type: docType };
if (promptVersion !== undefined) inputPayload.prompt_version = promptVersion;
if (body.model !== undefined) inputPayload.model = model;
const requestState = { flow_type: 'document', input_payload: inputPayload, model, started_at_ms: Date.now() };
function normalizeForHash(value) { if (Array.isArray(value)) return value.map(normalizeForHash); if (value && typeof value === 'object') { const normalized = {}; for (const key of Object.keys(value).sort()) normalized[key] = normalizeForHash(value[key]); return normalized; } return value; }
function createPayloadHash(text) { let h1 = 0xdeadbeef ^ text.length; let h2 = 0x41c6ce57 ^ text.length; for (let index = 0; index < text.length; index += 1) { const ch = text.charCodeAt(index); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); return `${(h2 >>> 0).toString(16).padStart(8, '0')}${(h1 >>> 0).toString(16).padStart(8, '0')}`; }
function sql(value) { return String(value).replaceAll("'", "''"); }
const normalizedPayloadText = JSON.stringify(normalizeForHash(inputPayload));
const requestHash = createPayloadHash(normalizedPayloadText);
const stateJson = JSON.stringify(requestState);
const inputJson = JSON.stringify(inputPayload);
const cacheLookupQuery = `WITH request_data AS (\n  SELECT '${sql(inputJson)}'::jsonb AS input_payload,\n         '${sql(stateJson)}'::jsonb AS request_state,\n         '${sql(requestHash)}'::text AS request_hash\n), cached AS (\n  SELECT id, output_payload\n  FROM executions\n  WHERE flow_type = 'document'\n    AND status = 'success'\n    AND request_hash = (SELECT request_hash FROM request_data)\n  ORDER BY created_at DESC\n  LIMIT 1\n)\nSELECT (SELECT request_hash FROM request_data) AS request_hash,\n       EXISTS(SELECT 1 FROM cached) AS cache_hit,\n       (SELECT id::text FROM cached) AS source_execution_id,\n       (SELECT output_payload FROM cached) AS output_payload,\n       (SELECT request_state FROM request_data) AS request_state;`;
return [{ json: { request_state: requestState, cache_lookup_query: cacheLookupQuery } }];

const prepared = $('Prepare Document Request').first().json;
if (!prepared?.cache_lookup_query) throw new Error('Cache lookup query was not prepared.');
return [{ json: prepared }];

const state = $json.request_state;
const requestHash = String($json.request_hash);
const sourceExecutionId = String($json.source_execution_id);
const outputPayload = $json.output_payload;
const durationMs = Math.max(0, Date.now() - Number(state.started_at_ms ?? Date.now()));
function sql(value) { return String(value).replaceAll("'", "''"); }
const stateJson = JSON.stringify(state);
const inputJson = JSON.stringify(state.input_payload);
const outputJson = JSON.stringify(outputPayload);
const query = `INSERT INTO executions (id, flow_type, status, input_payload, output_payload, request_hash, cache_hit, source_execution_id, duration_ms)
VALUES (gen_random_uuid(), 'document', 'success', '${sql(inputJson)}'::jsonb, '${sql(outputJson)}'::jsonb, '${sql(requestHash)}', true, '${sql(sourceExecutionId)}'::uuid, ${durationMs})
RETURNING id::text AS execution_id, output_payload AS response, '${sql(requestHash)}' AS request_hash, '${sql(sourceExecutionId)}' AS source_execution_id, ${durationMs}::integer AS duration_ms, '${sql(stateJson)}'::jsonb AS request_state;`;
return [{ json: { create_cache_hit_query: query } }];

const executionId = String($json.execution_id);
const requestHash = String($json.request_hash);
const sourceExecutionId = String($json.source_execution_id);
const response = $json.response;
const durationMs = Number($json.duration_ms ?? 0);
function sql(value) { return String(value).replaceAll("'", "''"); }
const inputPayload = JSON.stringify({ requestHash });
const outputPayload = JSON.stringify({ cacheHit: true, sourceExecutionId });
const responseJson = JSON.stringify(response);
const query = `WITH inserted AS (
  INSERT INTO execution_steps (execution_id, node_name, kind, status, input_payload, output_payload, duration_ms)
  VALUES ('${sql(executionId)}'::uuid, 'cache_lookup', 'cache', 'success', '${sql(inputPayload)}'::jsonb, '${sql(outputPayload)}'::jsonb, ${durationMs})
  RETURNING execution_id
)
SELECT '${sql(responseJson)}'::jsonb AS response;`;
return [{ json: { record_cached_step_query: query } }];

const state = $json.request_state;
const requestHash = String($json.request_hash);
function sql(value) { return String(value).replaceAll("'", "''"); }
const inputJson = JSON.stringify(state.input_payload);
const stateJson = JSON.stringify(state);
const query = `INSERT INTO executions (id, flow_type, status, input_payload, request_hash, cache_hit)
VALUES (gen_random_uuid(), 'document', 'pending', '${sql(inputJson)}'::jsonb, '${sql(requestHash)}', false)
RETURNING id::text AS execution_id, request_hash, '${sql(stateJson)}'::jsonb AS request_state;`;
return [{ json: { create_pending_query: query } }];

const state = $json.request_state;
const executionId = String($json.execution_id);
const requestHash = String($json.request_hash);
const durationMs = Math.max(0, Date.now() - Number(state.started_at_ms ?? Date.now()));
function sql(value) { return String(value).replaceAll("'", "''"); }
const stateJson = JSON.stringify(state);
const inputPayload = JSON.stringify({ requestHash });
const outputPayload = JSON.stringify({ cacheHit: false });
const query = `WITH inserted AS (
  INSERT INTO execution_steps (execution_id, node_name, kind, status, input_payload, output_payload, duration_ms)
  VALUES ('${sql(executionId)}'::uuid, 'cache_lookup', 'cache', 'success', '${sql(inputPayload)}'::jsonb, '${sql(outputPayload)}'::jsonb, ${durationMs})
  RETURNING execution_id
)
SELECT '${sql(executionId)}' AS execution_id, '${sql(requestHash)}' AS request_hash, '${sql(stateJson)}'::jsonb AS request_state;`;
return [{ json: { record_cache_step_query: query } }];

const state = $json.request_state;
const input = state.input_payload;
const executionId = String($json.execution_id);
const requestHash = String($json.request_hash);
const promptData = { agent: { role: 'Voce e um Tech Writer Senior e Product Manager Tecnico do sistema CPJ-Cobranca. Sua missao e gerar documentacao rica, precisa e util para o dominio de recuperacao de credito, adaptando o vocabulario para desenvolvedores quando doc_type for technical e para negocio/operacoes quando for operational.', instructions: ['Responda somente JSON valido com doc_type, title, description, inputs, outputs, side_effects, usage_example e notes.', 'Analise code, language e obedeca estritamente ao doc_type solicitado.', 'Para technical, foque assinaturas, tipos, dependencias, excecoes, efeitos colaterais e detalhes de implementacao.', 'Para operational, elimine jargoes de programacao e foque valor de negocio, comportamento visivel e impacto na cobranca.', 'Em inputs e outputs, liste parametros e retornos com name, type e description.', 'Em side_effects, liste alteracoes de estado, banco, webhooks, logs ou chamadas externas; use array vazio se for regra pura.', 'Em notes, destaque riscos tecnicos, LGPD, testabilidade ou regras engessadas.'] } };
const exportPatterns = [{ kind: 'function', pattern: /^\s*export\s+(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/ }, { kind: 'function', pattern: /^\s*export\s+default\s+(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/ }, { kind: 'class', pattern: /^\s*export\s+class\s+([A-Za-z_$][\w$]*)/ }, { kind: 'constant', pattern: /^\s*export\s+(?:const|let|var)\s+([A-Za-z_$][\w$]*)/ }, { kind: 'interface', pattern: /^\s*export\s+interface\s+([A-Za-z_$][\w$]*)/ }, { kind: 'type', pattern: /^\s*export\s+type\s+([A-Za-z_$][\w$]*)/ }];
const sideEffectPattern = /\b([A-Za-z_$][\w$]*\.(?:save|create|update|delete|insert|post|get|put|patch|request|send))\s*\(/g;
const lines = input.code.split('\n');
function extractPublicApiCandidates(lines) { const candidates = []; lines.forEach((line, index) => { for (const { kind, pattern } of exportPatterns) { const match = pattern.exec(line); if (match?.[1]) candidates.push({ name: match[1], kind, line_hint: `linha ${index + 1}` }); } }); return candidates; }
function hasImmediateJsDoc(lines, lineHint) { if (!lineHint) return false; const lineNumber = Number(String(lineHint).replace('linha ', '')); const previousLine = lines[lineNumber - 2]?.trim(); return Boolean(previousLine?.startsWith('/**') || previousLine?.endsWith('*/')); }
function findMissingPublicApiComments(lines, publicApiCandidates) { return publicApiCandidates.filter((candidate) => !hasImmediateJsDoc(lines, candidate.line_hint)).map((candidate) => ({ kind: 'missing_public_api_comment', target: candidate.name, confidence: 'low', description: 'API publica exportada sem comentario JSDoc imediatamente anterior.' })); }
function findPossibleSideEffects(code) { const findings = new Map(); for (const match of code.matchAll(sideEffectPattern)) { const target = match[1]; if (!target || findings.has(target)) continue; findings.set(target, { kind: 'possible_side_effect', target, confidence: 'medium', description: 'Codigo sugere persistencia ou chamada externa que deve ser documentada.' }); } return [...findings.values()]; }
const publicApiCandidates = extractPublicApiCandidates(lines);
const findings = [...findMissingPublicApiComments(lines, publicApiCandidates), ...findPossibleSideEffects(input.code)];
const toolResult = { publicApiCandidates, findings };
const systemPrompt = `${promptData.agent.role}\n\nLinguagem: ${input.language}\nTipo de documentacao: ${input.doc_type}\n\nInstrucoes:\n${promptData.agent.instructions.map((instruction) => `- ${instruction}`).join('\n')}\n\nContrato de saida estruturada: responda somente JSON valido com este formato exato: {"doc_type":"technical|operational","title":"string","description":"string","inputs":[{"name":"string","type":"string","description":"string"}],"outputs":[{"name":"string","type":"string","description":"string"}],"side_effects":["string"],"usage_example":"string","notes":"string|null"}.`;
const userPrompt = JSON.stringify({ doc_type: input.doc_type, codigo: input.code, api_publica_detectada: publicApiCandidates, sinais_deterministicos: findings }, null, 2);
return [{ json: { execution_id: executionId, request_hash: requestHash, request_state: state, language: input.language, doc_type: input.doc_type, tool_result: toolResult, document_system_prompt: systemPrompt, document_user_prompt: userPrompt } }];

const context = $('Document Signal Extractor').first().json;
const raw = $json.output ?? $json.text ?? $json.response ?? $json;
function cleanJsonText(value) { return String(value ?? '').trim().replace(/^```json/i, '').replace(/^```/i, '').replace(/```$/i, '').trim(); }
function normalizeStringArray(value) { return Array.isArray(value) ? value.map(String).map((item) => item.trim()).filter(Boolean) : []; }
function normalizeIoItems(value) { return Array.isArray(value) ? value.map((item) => ({ name: String(item?.name ?? 'item').trim() || 'item', type: String(item?.type ?? 'unknown').trim() || 'unknown', description: String(item?.description ?? '').trim() || 'Sem descricao inferida.' })) : []; }
function normalizeDocument(value) { const docType = ['technical', 'operational'].includes(value.doc_type) ? value.doc_type : context.doc_type; return { doc_type: docType, title: String(value.title ?? 'Documentacao gerada').trim() || 'Documentacao gerada', description: String(value.description ?? 'Documentacao gerada a partir do codigo informado.').trim() || 'Documentacao gerada a partir do codigo informado.', inputs: normalizeIoItems(value.inputs), outputs: normalizeIoItems(value.outputs), side_effects: normalizeStringArray(value.side_effects), usage_example: String(value.usage_example ?? 'Sem exemplo inferido.').trim() || 'Sem exemplo inferido.', notes: value.notes == null ? null : String(value.notes).trim() || null }; }
function parseDocumentOutput(value) { if (typeof value === 'object' && value !== null && !Array.isArray(value)) return normalizeDocument(value); const text = cleanJsonText(value); try { return normalizeDocument(JSON.parse(text)); } catch { return { doc_type: context.doc_type, title: 'Documentacao indisponivel', description: 'O agente retornou conteudo fora do JSON estruturado esperado.', inputs: [], outputs: [], side_effects: [], usage_example: 'Reexecute a geracao de documentacao apos ajustar o prompt/schema.', notes: text.slice(0, 500) || 'Saida invalida do agente de documentacao.' }; } }
function sql(value) { return String(value).replaceAll("'", "''"); }
function estimateTokens(value) { return Math.ceil(String(value ?? '').length / 4); }
const response = parseDocumentOutput(raw);
const executionId = context.execution_id;
const durationMs = Math.max(0, Date.now() - Number(context.request_state.started_at_ms ?? Date.now()));
const responseJson = JSON.stringify(response);
const promptText = [context.document_system_prompt, context.document_user_prompt].join('\n');
const completionText = JSON.stringify(response);
const promptTokens = estimateTokens(promptText);
const completionTokens = estimateTokens(completionText);
const totalTokens = promptTokens + completionTokens;
const inputCostUsd = Number(((promptTokens / 1000000) * 0.15).toFixed(8));
const outputCostUsd = Number(((completionTokens / 1000000) * 0.60).toFixed(8));
const costUsd = Number((inputCostUsd + outputCostUsd).toFixed(8));
const stepRows = [];
function addStep(nodeName, kind, inputPayload, outputPayload) { stepRows.push(`('${sql(executionId)}'::uuid, '${sql(nodeName)}', '${sql(kind)}', 'success', '${sql(JSON.stringify(inputPayload ?? null))}'::jsonb, '${sql(JSON.stringify(outputPayload ?? null))}'::jsonb, 0)`); }
addStep('document_signal_extractor', 'tool', { language: context.language, doc_type: context.doc_type }, context.tool_result);
addStep('document_agent', 'llm', { publicApiCandidates: context.tool_result.publicApiCandidates, findings: context.tool_result.findings }, response);
const persistSuccessQuery = `WITH updated AS (\n  UPDATE executions\n  SET status = 'success', output_payload = '${sql(responseJson)}'::jsonb, duration_ms = ${durationMs}, error_message = NULL, updated_at = NOW()\n  WHERE id = '${sql(executionId)}'::uuid\n  RETURNING id\n), inserted_steps AS (\n  INSERT INTO execution_steps (execution_id, node_name, kind, status, input_payload, output_payload, duration_ms)\n  VALUES ${stepRows.join(',\n         ')}\n  RETURNING execution_id\n)\nSELECT '${sql(responseJson)}'::jsonb AS response, '${sql(executionId)}' AS execution_id, ${durationMs}::integer AS duration_ms, ${promptTokens}::integer AS prompt_tokens, ${completionTokens}::integer AS completion_tokens, ${totalTokens}::integer AS total_tokens, ${costUsd}::numeric(12,8) AS cost_usd, ${inputCostUsd}::numeric(12,8) AS input_cost_usd, ${outputCostUsd}::numeric(12,8) AS output_cost_usd, '${sql(context.request_state.model)}' AS model_used;`;
const telemetryQuery = `INSERT INTO execution_telemetry (execution_id, provider, model_requested, model_used, prompt_tokens, completion_tokens, total_tokens, cost_usd, input_cost_usd, output_cost_usd, cache_read_tokens)\nVALUES ('${sql(executionId)}'::uuid, 'openrouter', '${sql(context.request_state.model)}', '${sql(context.request_state.model)}', ${promptTokens}, ${completionTokens}, ${totalTokens}, ${costUsd}, ${inputCostUsd}, ${outputCostUsd}, NULL)\nON CONFLICT (execution_id) DO UPDATE SET model_used = EXCLUDED.model_used, prompt_tokens = EXCLUDED.prompt_tokens, completion_tokens = EXCLUDED.completion_tokens, total_tokens = EXCLUDED.total_tokens, cost_usd = EXCLUDED.cost_usd, input_cost_usd = EXCLUDED.input_cost_usd, output_cost_usd = EXCLUDED.output_cost_usd, cache_read_tokens = EXCLUDED.cache_read_tokens\nRETURNING '${sql(responseJson)}'::jsonb AS response;`;
return [{ json: { response, persist_success_query: persistSuccessQuery, telemetry_query: telemetryQuery } }];

const normalized = $('Normalize Document Output').first().json;
if (!normalized?.telemetry_query) throw new Error('Telemetry query was not prepared.');
return [{ json: normalized }];
